package br.com.onda;
import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.function.Consumer;import org.json.*;
/** City lookup only after an explicit request. No GPS, autocomplete or background polling. */
final class RadioCity {
 final String name,state,countryCode,country;final double latitude,longitude;
 static final double RADIUS_KM=50;private static final Object REQUEST_LOCK=new Object();private static long lastRequest;
 RadioCity(String name,String state,String code,String country,double lat,double lon){this.name=clean(name,100);this.state=clean(state,100);this.country=clean(country,100);this.countryCode=code==null?"":code.toUpperCase(Locale.ROOT);if(this.name.isEmpty()||!this.countryCode.matches("[A-Z]{2}")||!coordinate(lat,lon))throw new IllegalArgumentException("Cidade inválida.");latitude=lat;longitude=lon;}
 private static String clean(String s,int max){String v=s==null?"":s.replaceAll("[\\p{Cntrl}\\s]+"," ").trim();return v.substring(0,Math.min(max,v.length()));}
 static boolean coordinate(double lat,double lon){return Double.isFinite(lat)&&Double.isFinite(lon)&&Math.abs(lat)<=90&&Math.abs(lon)<=180;}
 double distance(double lat,double lon){if(!coordinate(lat,lon))return Double.POSITIVE_INFINITY;double a=Math.toRadians(latitude),b=Math.toRadians(lat),dl=Math.toRadians(lat-latitude),dn=Math.toRadians(lon-longitude);double h=Math.sin(dl/2)*Math.sin(dl/2)+Math.cos(a)*Math.cos(b)*Math.sin(dn/2)*Math.sin(dn/2);return 12742*Math.asin(Math.sqrt(Math.max(0,Math.min(1,h))));}
 String label(){return name+(state.isEmpty()||state.equalsIgnoreCase(name)?"":" • "+state)+" • "+(country.isEmpty()?countryCode:country);}
 String key(){return countryCode+":"+Math.round(latitude*10000)+":"+Math.round(longitude*10000);}
 JSONObject json()throws JSONException{return new JSONObject().put("name",name).put("state",state).put("code",countryCode).put("country",country).put("lat",latitude).put("lon",longitude);}
 static RadioCity decode(String value){try{JSONObject o=new JSONObject(value);return new RadioCity(o.optString("name"),o.optString("state"),o.optString("code"),o.optString("country"),o.getDouble("lat"),o.getDouble("lon"));}catch(Exception e){return null;}}
 static String write(List<RadioCity> cities){JSONArray a=new JSONArray();for(RadioCity c:cities)if(a.length()<10)try{a.put(c.json());}catch(JSONException ignored){}return a.toString();}
 static List<RadioCity> read(String raw){ArrayList<RadioCity> out=new ArrayList<>();try{JSONArray a=new JSONArray(raw);for(int i=0;i<Math.min(10,a.length());i++){RadioCity c=decode(a.getJSONObject(i).toString());if(c!=null)out.add(c);}}catch(Exception ignored){}return out;}
 static String searchUrl(String term,boolean brazil){String q=clean(term,121);if(q.isEmpty()||q.length()>120)throw new IllegalArgumentException("Digite uma cidade, até 120 caracteres.");try{return "https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&featureType=city&limit=5"+(brazil?"&countrycodes=br":"")+"&q="+URLEncoder.encode(q,"UTF-8");}catch(UnsupportedEncodingException impossible){throw new IllegalStateException(impossible);}}
 static List<RadioCity> parse(String raw,boolean brazil)throws JSONException{JSONArray a=new JSONArray(raw);ArrayList<RadioCity> out=new ArrayList<>();Set<String> seen=new HashSet<>();for(int i=0;i<Math.min(10,a.length());i++)try{JSONObject o=a.getJSONObject(i),address=o.getJSONObject("address");String code=address.optString("country_code","").toUpperCase(Locale.ROOT);if(brazil&&!code.equals("BR"))continue;String name="";for(String key:new String[]{"city","town","village","municipality"})if(!address.optString(key).isEmpty()){name=address.getString(key);break;}if(name.isEmpty()&&Arrays.asList("city","town","village","municipality").contains(o.optString("addresstype")))name=o.optString("name");RadioCity c=new RadioCity(name,address.optString("state"),code,address.optString("country"),o.getDouble("lat"),o.getDouble("lon"));if(seen.add(c.key()))out.add(c);}catch(Exception ignored){}return out;}
 static List<RadioCity> search(String term,boolean brazil,Consumer<HttpURLConnection> active)throws Exception{String url=searchUrl(term,brazil);synchronized(REQUEST_LOCK){long now=System.nanoTime(),remaining=lastRequest==0?0:1_050_000_000L-(now-lastRequest);if(remaining>0)Thread.sleep((remaining+999999)/1000000);lastRequest=System.nanoTime();}if(Thread.currentThread().isInterrupted())throw new InterruptedException();HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();active.accept(c);try{c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Onda/0.69.0 (+https://github.com/cristianoarakaki-cpu/Arakaki)");c.setRequestProperty("Accept","application/json");c.setRequestProperty("Accept-Language","pt-BR,pt;q=0.9");c.setRequestProperty("Accept-Encoding","gzip");if(c.getResponseCode()!=200)throw new IOException("Busca de cidades indisponível.");InputStream input=c.getInputStream();if("gzip".equalsIgnoreCase(c.getContentEncoding()))input=new java.util.zip.GZIPInputStream(input);try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedException();if(out.size()+n>256*1024)throw new IOException("Resposta de cidades muito grande.");out.write(b,0,n);}return parse(out.toString(StandardCharsets.UTF_8.name()),brazil);}}finally{c.disconnect();}}
}
